import{_ as e,c as o,o as d,ae as r}from"./chunks/framework.Cd-3tpCq.js";const h=JSON.parse('{"title":"Product Sub-Resources (Product tag)","description":"","frontmatter":{"outline":false,"examples":[{"id":"list-product-images","title":"Images — List for a product","description":"All images attached to a single product. The same data is also inlined under `images[]` in the [Single Product](/api/rest-api/shop/products/get-product) response — call this only when you need just the gallery.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2/images\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 969,\\n    \\"type\\": \\"images\\",\\n    \\"path\\": \\"product/2/XmdfIafCjuYEhHiBkHvzmOuDT0mpGHDTi9QhnUoY.webp\\",\\n    \\"productId\\": 2,\\n    \\"position\\": 1,\\n    \\"publicPath\\": \\"http://localhost/storage/product/2/XmdfIafCjuYEhHiBkHvzmOuDT0mpGHDTi9QhnUoY.webp\\"\\n  }\\n]\\n","commonErrors":[{"error":"404 Not Found","cause":"Parent product `{productId}` doesn\'t exist","solution":"Discover product IDs via `GET /api/shop/products`."}]},{"id":"list-product-images-root","title":"Images — Root collection","description":"Paginated list of every product image across all products. Useful for an admin gallery audit.","request":"curl -X GET \\"http://localhost/api/shop/product-images?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 1234\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 617\\n\\n[\\n  {\\n    \\"id\\": 4,\\n    \\"type\\": \\"images\\",\\n    \\"path\\": \\"product/4/nRO8G2ljoUejAr6agYhx5eZTUwBIeft61dNRwNw6.webp\\",\\n    \\"productId\\": 4,\\n    \\"position\\": 1,\\n    \\"publicPath\\": \\"http://localhost/storage/product/4/nRO8G2ljoUejAr6agYhx5eZTUwBIeft61dNRwNw6.webp\\"\\n  }\\n]\\n"},{"id":"get-product-image","title":"Images — Single by ID","description":"Resolve a single image by its global ID (e.g. an ID stored on a wishlist or order line).","request":"curl -X GET \\"http://localhost/api/shop/product-images/969\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 969,\\n  \\"type\\": \\"images\\",\\n  \\"path\\": \\"product/2/XmdfIafCjuYEhHiBkHvzmOuDT0mpGHDTi9QhnUoY.webp\\",\\n  \\"productId\\": 2,\\n  \\"position\\": 1,\\n  \\"publicPath\\": \\"http://localhost/storage/product/2/XmdfIafCjuYEhHiBkHvzmOuDT0mpGHDTi9QhnUoY.webp\\"\\n}\\n"},{"id":"list-product-videos","title":"Videos — List for a product","description":"Same shape as images, just video assets. Inlined under `videos[]` on the Single Product response.","request":"curl -X GET \\"http://localhost/api/shop/products/2/videos\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 12,\\n    \\"type\\": \\"videos\\",\\n    \\"path\\": \\"product/2/promo.mp4\\",\\n    \\"productId\\": 2,\\n    \\"position\\": 1,\\n    \\"publicPath\\": \\"http://localhost/storage/product/2/promo.mp4\\"\\n  }\\n]\\n"},{"id":"list-customer-group-prices","title":"Customer Group Prices — List for a product","description":"Tier (customer-group) prices configured on a product. Returns an empty array when no tier rules apply. **Customer group prices are not inlined** in the Single Product response — fetch them here when needed.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2/customer-group-prices\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 4,\\n    \\"qty\\": 5,\\n    \\"valueType\\": \\"fixed\\",\\n    \\"value\\": 80,\\n    \\"customerGroupId\\": 2,\\n    \\"uniqueId\\": \\"2|2|5\\",\\n    \\"productId\\": 2\\n  }\\n]\\n"},{"id":"list-customizable-options","title":"Customizable Options — List for a product","description":"Per-product custom inputs (text fields, file uploads, dropdowns added by the merchant). Inlined under `customizableOptions[]` on the Single Product response — fetch here only when you need the slice.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/14/customizable-options\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"type\\": \\"field\\",\\n    \\"isRequired\\": 1,\\n    \\"sortOrder\\": 0,\\n    \\"product\\": \\"/api/shop/products/14\\",\\n    \\"prices\\": [\\"/api/shop/product_customizable_option_prices/1\\"],\\n    \\"translation\\": \\"/api/shop/product_customizable_option_translations/1\\",\\n    \\"translations\\": [\\n      \\"/api/shop/product_customizable_option_translations/1\\",\\n      \\"/api/shop/product_customizable_option_translations/4\\"\\n    ]\\n  }\\n]\\n"},{"id":"get-customizable-option","title":"Customizable Options — Single (snake_case URL)","description":"Resolve a single customizable option by ID. The URL is underscored — `product_customizable_options`, not `product-customizable-options`. There is no collection at that path; reach the list through `/products/{productId}/customizable-options`, whose rows carry these IRIs.\\n","request":"curl -X GET \\"http://localhost/api/shop/product_customizable_options/12\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 1,\\n  \\"type\\": \\"field\\",\\n  \\"isRequired\\": 1,\\n  \\"sortOrder\\": 0,\\n  \\"product\\": \\"/api/shop/products/14\\",\\n  \\"prices\\": [\\"/api/shop/product_customizable_option_prices/1\\"],\\n  \\"translation\\": \\"/api/shop/product_customizable_option_translations/1\\",\\n  \\"translations\\": [\\n    \\"/api/shop/product_customizable_option_translations/1\\",\\n    \\"/api/shop/product_customizable_option_translations/4\\"\\n  ]\\n}\\n"},{"id":"list-customizable-option-prices","title":"Customizable Option Prices","description":"Sub-resource of customizable options — pricing rows referenced by the option\'s `prices[]` IRI array.\\n","request":"curl -X GET \\"http://localhost/api/shop/product_customizable_option_prices?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\nX-Total-Count: 7\\nX-Page: 1\\nX-Per-Page: 2\\nX-Total-Pages: 4\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"price\\": 5,\\n    \\"priceType\\": \\"fixed\\",\\n    \\"customizableOption\\": \\"/api/shop/product_customizable_options/1\\"\\n  }\\n]\\n"},{"id":"list-customizable-option-translations","title":"Customizable Option Translations","description":"Locale-specific labels for a customizable option. Reached by following the `translation` / `translations[]` IRIs on the parent option.\\n","request":"curl -X GET \\"http://localhost/api/shop/product_customizable_option_translations?per_page=2\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 1,\\n    \\"locale\\": \\"en\\",\\n    \\"label\\": \\"Engraving\\",\\n    \\"customizableOption\\": \\"/api/shop/product_customizable_options/1\\"\\n  }\\n]\\n"},{"id":"list-attribute-values","title":"Attribute Values — List for a product","description":"The raw EAV value rows for a product (one per attribute × locale × channel). The Single Product response surfaces typed fields (`name`, `description`, `price`, `color`, `size`, `brand`, …) instead — only call this endpoint when you need the underlying EAV record.\\n","request":"curl -X GET \\"http://localhost/api/shop/products/2/attribute-values\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": 25,\\n    \\"locale\\": \\"en\\",\\n    \\"channel\\": \\"default\\",\\n    \\"textValue\\": \\"Step into timeless style…\\",\\n    \\"value\\": \\"Step into timeless style…\\",\\n    \\"uniqueId\\": \\"default|en|2|9\\",\\n    \\"attribute\\": \\"/api/shop/attributes/9\\",\\n    \\"product\\": \\"/api/shop/products/2\\"\\n  }\\n]\\n"}]},"headers":[],"relativePath":"api/rest-api/shop/products/product-subresources.md","filePath":"api/rest-api/shop/products/product-subresources.md"}'),i={name:"api/rest-api/shop/products/product-subresources.md"};function a(s,t,n,c,p,l){return d(),o("div",null,t[0]||(t[0]=[r('<h1 id="product-sub-resources-product-tag" tabindex="-1">Product Sub-Resources (<code>Product</code> tag) <a class="header-anchor" href="#product-sub-resources-product-tag" aria-label="Permalink to &quot;Product Sub-Resources (`Product` tag)&quot;">​</a></h1><p>Sub-resources of a product — gallery assets, tier prices, customizable options and their pricing/translations, raw EAV values. Most of these are already inlined on the <a href="/api/rest-api/shop/products/get-product.html">Single Product</a> response; the dedicated endpoints listed here exist when you need just one slice without re-fetching the whole PDP.</p><h2 id="url-naming-is-not-uniform" tabindex="-1">URL naming is not uniform <a class="header-anchor" href="#url-naming-is-not-uniform" aria-label="Permalink to &quot;URL naming is not uniform&quot;">​</a></h2><p>Root URLs in this group use two different separators, so a path cannot be guessed from the resource name:</p><table tabindex="0"><thead><tr><th>Separator</th><th>Endpoints</th></tr></thead><tbody><tr><td>Dashed</td><td><code>*-images</code>, <code>*-videos</code>, <code>*-bundle-option-products</code>, <code>*-downloadable-links</code>, <code>*-downloadable-samples</code></td></tr><tr><td>Underscored</td><td><code>product_customizable_options</code>, <code>product_customizable_option_prices</code>, <code>product_customizable_option_translations</code>, <code>product_bundle_options</code>, <code>product_grouped_products</code></td></tr></tbody></table><p>The underscored form is the framework&#39;s default snake-case route, kept where no explicit path was declared. Copy the URL from the parent resource&#39;s IRI rather than assembling it by hand — the IRIs in a response are authoritative.</p><h2 id="endpoints-in-this-group" tabindex="-1">Endpoints in this group <a class="header-anchor" href="#endpoints-in-this-group" aria-label="Permalink to &quot;Endpoints in this group&quot;">​</a></h2><h3 id="images-type-images" tabindex="-1">Images (<code>type = images</code>) <a class="header-anchor" href="#images-type-images" aria-label="Permalink to &quot;Images (`type = images`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/images</code></td><td>All images for a product (nested)</td></tr><tr><td>GET</td><td><code>/api/shop/product-images</code></td><td>Paginated, every image across the catalog (root)</td></tr><tr><td>GET</td><td><code>/api/shop/product-images/{id}</code></td><td>Single image by global ID</td></tr></tbody></table><h3 id="videos-type-videos" tabindex="-1">Videos (<code>type = videos</code>) <a class="header-anchor" href="#videos-type-videos" aria-label="Permalink to &quot;Videos (`type = videos`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/videos</code></td><td>All videos for a product (nested)</td></tr><tr><td>GET</td><td><code>/api/shop/product-videos</code></td><td>Paginated root collection</td></tr><tr><td>GET</td><td><code>/api/shop/product-videos/{id}</code></td><td>Single video by global ID</td></tr></tbody></table><p>Same response shape as Images, with <code>type: &quot;videos&quot;</code>.</p><h3 id="customer-group-prices-tier-prices" tabindex="-1">Customer Group Prices (tier prices) <a class="header-anchor" href="#customer-group-prices-tier-prices" aria-label="Permalink to &quot;Customer Group Prices (tier prices)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/customer-group-prices</code></td><td>Tier prices for a product</td></tr></tbody></table><p>The nested list is the only tier-price endpoint. There is no single-row route and no root collection — reading one row means reading the product&#39;s list and picking it out.</p><h3 id="customizable-options-prices-translations" tabindex="-1">Customizable Options + Prices + Translations <a class="header-anchor" href="#customizable-options-prices-translations" aria-label="Permalink to &quot;Customizable Options + Prices + Translations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/customizable-options</code></td><td>All custom inputs for a product (nested)</td></tr><tr><td>GET</td><td><code>/api/shop/product_customizable_options/{id}</code></td><td>Single option by ID</td></tr><tr><td>GET</td><td><code>/api/shop/product_customizable_option_prices</code></td><td>Paginated pricing rows</td></tr><tr><td>GET</td><td><code>/api/shop/product_customizable_option_prices/{id}</code></td><td>Single pricing row</td></tr><tr><td>GET</td><td><code>/api/shop/product_customizable_option_translations</code></td><td>Paginated locale labels</td></tr><tr><td>GET</td><td><code>/api/shop/product_customizable_option_translations/{id}</code></td><td>Single label</td></tr></tbody></table><h3 id="attribute-values-raw-eav-—-sub-resource-only" tabindex="-1">Attribute Values (raw EAV — sub-resource only) <a class="header-anchor" href="#attribute-values-raw-eav-—-sub-resource-only" aria-label="Permalink to &quot;Attribute Values (raw EAV — sub-resource only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/shop/products/{productId}/attribute-values</code></td><td>Every attribute value row for a product</td></tr></tbody></table><p>There is no root collection and no single-row endpoint. Read the values through the product itself.</p><h2 id="response-field-reference" tabindex="-1">Response field reference <a class="header-anchor" href="#response-field-reference" aria-label="Permalink to &quot;Response field reference&quot;">​</a></h2><h3 id="image-video" tabindex="-1">Image / Video <a class="header-anchor" href="#image-video" aria-label="Permalink to &quot;Image / Video&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Asset primary key</td></tr><tr><td><code>type</code></td><td>string</td><td><code>images</code> or <code>videos</code></td></tr><tr><td><code>path</code></td><td>string</td><td>Storage path (relative)</td></tr><tr><td><code>productId</code></td><td>integer</td><td>Owning product</td></tr><tr><td><code>position</code></td><td>integer</td><td>Display order</td></tr><tr><td><code>publicPath</code></td><td>string</td><td>Fully-qualified URL</td></tr></tbody></table><h3 id="customer-group-price" tabindex="-1">Customer Group Price <a class="header-anchor" href="#customer-group-price" aria-label="Permalink to &quot;Customer Group Price&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Tier-price row ID</td></tr><tr><td><code>qty</code></td><td>number</td><td>Threshold quantity for this tier</td></tr><tr><td><code>valueType</code></td><td>string</td><td><code>fixed</code> (replaces price) or <code>discount</code> (percentage off)</td></tr><tr><td><code>value</code></td><td>number</td><td>Tier value — interpreted by <code>valueType</code></td></tr><tr><td><code>customerGroupId</code></td><td>integer</td><td>Customer group this tier applies to</td></tr><tr><td><code>uniqueId</code></td><td>string</td><td>Internal lookup key (<code>&lt;group&gt;|&lt;product&gt;|&lt;qty&gt;</code>)</td></tr><tr><td><code>productId</code></td><td>integer</td><td>Owning product</td></tr></tbody></table><h3 id="customizable-option" tabindex="-1">Customizable Option <a class="header-anchor" href="#customizable-option" aria-label="Permalink to &quot;Customizable Option&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Option primary key</td></tr><tr><td><code>type</code></td><td>string</td><td><code>field</code>, <code>area</code>, <code>drop_down</code>, <code>radio</code>, <code>checkbox</code>, <code>multiple</code>, <code>date</code>, <code>date_time</code>, <code>time</code>, <code>file</code></td></tr><tr><td><code>isRequired</code></td><td>boolean (0/1)</td><td>Whether the customer must fill the option</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order on the PDP</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Parent product</td></tr><tr><td><code>prices</code></td><td>array (IRI)</td><td>One IRI per pricing row — dereference for the actual prices</td></tr><tr><td><code>translation</code></td><td>string (IRI)</td><td>Translation for the request locale</td></tr><tr><td><code>translations</code></td><td>array (IRI)</td><td>All locale translations</td></tr></tbody></table><h3 id="customizable-option-price" tabindex="-1">Customizable Option Price <a class="header-anchor" href="#customizable-option-price" aria-label="Permalink to &quot;Customizable Option Price&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Pricing row primary key</td></tr><tr><td><code>price</code></td><td>number</td><td>Price increment for this option</td></tr><tr><td><code>priceType</code></td><td>string</td><td><code>fixed</code> or <code>percent</code></td></tr><tr><td><code>customizableOption</code></td><td>string (IRI)</td><td>Parent customizable option</td></tr></tbody></table><h3 id="customizable-option-translation" tabindex="-1">Customizable Option Translation <a class="header-anchor" href="#customizable-option-translation" aria-label="Permalink to &quot;Customizable Option Translation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Translation row primary key</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code</td></tr><tr><td><code>label</code></td><td>string</td><td>Localized option label shown to the customer</td></tr><tr><td><code>customizableOption</code></td><td>string (IRI)</td><td>Parent customizable option</td></tr></tbody></table><h3 id="attribute-value" tabindex="-1">Attribute Value <a class="header-anchor" href="#attribute-value" aria-label="Permalink to &quot;Attribute Value&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>EAV row primary key</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale this value applies to</td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code</td></tr><tr><td><code>textValue</code> / <code>integerValue</code> / <code>decimalValue</code> / <code>booleanValue</code> / <code>datetimeValue</code> / <code>dateValue</code> / <code>jsonValue</code></td><td>mixed</td><td>The typed storage column — only one is populated per row, depending on the attribute&#39;s <code>columnName</code></td></tr><tr><td><code>value</code></td><td>mixed</td><td>Convenience accessor — same as the populated typed column</td></tr><tr><td><code>uniqueId</code></td><td>string</td><td><code>&lt;channel&gt;|&lt;locale&gt;|&lt;product&gt;|&lt;attribute&gt;</code> — internal index</td></tr><tr><td><code>attribute</code></td><td>string (IRI)</td><td>Parent attribute</td></tr><tr><td><code>product</code></td><td>string (IRI)</td><td>Parent product</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Refresh the gallery</strong> without re-fetching the entire PDP after the customer changes a configurable variant — <code>GET /api/shop/products/{variantId}/images</code>.</li><li><strong>Audit assets</strong> across the catalog from an admin tool — <code>GET /api/shop/product-images?per_page=50</code> and walk the pagination.</li><li><strong>Display tier-price tables</strong> on a B2B PDP — <code>GET /api/shop/products/{id}/customer-group-prices</code>.</li><li><strong>Render a customizable-option editor</strong> — list the option from the PDP, then dereference each <code>prices[]</code> IRI for the per-option upcharge.</li><li><strong>Inspect the raw EAV record</strong> during a data-quality audit — <code>GET /api/shop/products/{id}/attribute-values</code> shows exactly what&#39;s stored on <code>product_attribute_values</code>.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/products/get-product.html">Single Product</a> — embeds <code>images</code>, <code>videos</code>, <code>customizableOptions</code>, … inline</li><li><a href="/api/rest-api/shop/products/product-type-subresources.html">Product Type Sub-Resources</a> — the per-type structure behind variants, bundles, and downloadables</li><li><a href="/api/rest-api/introduction.html#iris-hateoas">Introduction → IRIs &amp; HATEOAS</a> — how to dereference the path references in these payloads</li></ul>',37)]))}const x=e(i,[["render",a]]);export{h as __pageData,x as default};
